using System;using System.Linq;using HabitatShift.Core;using UnityEditor;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public static class R10Inspector { static readonly string[] Colors={"orange","blue","green","yellow","purple","cyan","pink","red","white","brown"};static void Mutate(R10EditorState s,string label,Action apply){Undo.RecordObject(s,label);apply();R10Storage.ResetCertification(s.project);EditorUtility.SetDirty(s);}static int ColorIndex(string color){var i=Array.IndexOf(Colors,color);return i<0?0:i;}public static void Draw(R10EditorState state,R10Selection x){if(state==null||state.project==null||!x.Has){EditorGUILayout.HelpBox("Select a habitat, sproutling, or elevator.",MessageType.Info);return;}var p=state.project;if(GUILayout.Button("DELETE")){R10Commands.Delete(state,x);return;}if(x.kind=="Habitat")Habitat(state,x,p.level.habitats.FirstOrDefault(v=>v.id==x.id));else if(x.kind=="Sproutling")Target(state,p.level.targets.FirstOrDefault(v=>v.id==x.id));else if(x.kind=="Elevator")Elevator(state,p.level.elevators.FirstOrDefault(v=>v.id==x.id));}static void Habitat(R10EditorState s,R10Selection x,HabitatDto h){if(h==null)return;EditorGUILayout.LabelField("HABITAT",EditorStyles.boldLabel);EditorGUI.BeginChangeCheck();var id=EditorGUILayout.TextField("ID",h.id);var c=EditorGUILayout.TextField("Constraint",h.movementConstraint);var ax=EditorGUILayout.IntField("Anchor X",h.anchor.x);var ay=EditorGUILayout.IntField("Anchor Y",h.anchor.y);var color=Colors[EditorGUILayout.Popup("Color",ColorIndex(h.stages==null?h.color:h.stages[0].color),Colors)];var need=EditorGUILayout.IntField("Need",h.stages==null?h.need:h.stages[0].need);if(EditorGUI.EndChangeCheck())Mutate(s,"Edit Habitat",()=>{h.id=id;h.movementConstraint=c;h.anchor=new IntPair{x=ax,y=ay};if(h.stages==null){h.color=color;h.need=Mathf.Max(1,need);}else{h.stages[0].color=color;h.stages[0].need=Mathf.Max(1,need);}});EditorGUILayout.Space();EditorGUILayout.LabelField("FOOTPRINT  "+(h.shape?.Length??0)+" cells",EditorStyles.boldLabel);var shape=h.shape??Array.Empty<IntPair>();var maxX=Mathf.Max(0,shape.Select(q=>q.x).DefaultIfEmpty(0).Max());var maxY=Mathf.Max(0,shape.Select(q=>q.y).DefaultIfEmpty(0).Max());for(var y=maxY;y>=0;y--){EditorGUILayout.BeginHorizontal();for(var xx=0;xx<=maxX;xx++){var cell=new IntPair{x=xx,y=y};var on=shape.Any(q=>q.x==xx&&q.y==y);if(GUILayout.Toggle(on,xx+","+y,GUILayout.Width(42))!=on){var next=on?shape.Where(q=>q.x!=xx||q.y!=y).ToArray():shape.Concat(new[]{cell}).ToArray();if(next.Length>0)Mutate(s,"Toggle Footprint",()=>h.shape=next);}}EditorGUILayout.EndHorizontal();}EditorGUILayout.BeginHorizontal();if(GUILayout.Button("NORMALIZE"))Mutate(s,"Normalize Footprint",()=>h.shape=Normalize(h.shape));if(GUILayout.Button("ROTATE 90"))Mutate(s,"Rotate Footprint",()=>h.shape=Normalize(h.shape.Select(q=>new IntPair{x=-q.y,y=q.x}).ToArray()));if(GUILayout.Button("RESET SINGLE"))Mutate(s,"Reset Footprint",()=>h.shape=new[]{new IntPair{x=0,y=0}});EditorGUILayout.EndHorizontal();}static IntPair[] Normalize(IntPair[] q){var x=q.Min(v=>v.x);var y=q.Min(v=>v.y);return q.Select(v=>new IntPair{x=v.x-x,y=v.y-y}).Distinct(new PairComparer()).ToArray();}static void Target(R10EditorState s,TargetDto t){if(t==null)return;EditorGUI.BeginChangeCheck();var color=Colors[EditorGUILayout.Popup("Color",ColorIndex(t.color),Colors)];if(EditorGUI.EndChangeCheck())Mutate(s,"Edit Sproutling",()=>t.color=color);}static void Elevator(R10EditorState s,ElevatorDto e){if(e==null)return;EditorGUI.BeginChangeCheck();var direction=EditorGUILayout.TextField("Direction",e.direction);var mandatory=EditorGUILayout.Toggle("Mandatory",e.mandatory);if(EditorGUI.EndChangeCheck())Mutate(s,"Edit Elevator",()=>{e.direction=direction;e.mandatory=mandatory;});var q=e.queue??Array.Empty<QueueItemDto>();for(var i=0;i<q.Length;i++){var item=q[i];EditorGUILayout.BeginHorizontal();EditorGUILayout.LabelField(item.id,GUILayout.Width(100));var color=Colors[EditorGUILayout.Popup(ColorIndex(item.color),Colors)];if(color!=item.color)Mutate(s,"Edit Queue",()=>item.color=color);if(GUILayout.Button("UP",GUILayout.Width(38))&&i>0)Mutate(s,"Move Queue Item",()=>{var a=e.queue[i-1];e.queue[i-1]=e.queue[i];e.queue[i]=a;});if(GUILayout.Button("DOWN",GUILayout.Width(50))&&i<q.Length-1)Mutate(s,"Move Queue Item",()=>{var a=e.queue[i+1];e.queue[i+1]=e.queue[i];e.queue[i]=a;});if(GUILayout.Button("DELETE",GUILayout.Width(58))){var n=i;Mutate(s,"Delete Queue Item",()=>e.queue=e.queue.Where((v,j)=>j!=n).ToArray());GUIUtility.ExitGUI();}EditorGUILayout.EndHorizontal();}if(GUILayout.Button("ADD ITEM"))Mutate(s,"Add Queue Item",()=>e.queue=q.Concat(new[]{new QueueItemDto{id=e.id+"_Q"+(q.Length+1).ToString("00"),color="green"}}).ToArray());}sealed class PairComparer:System.Collections.Generic.IEqualityComparer<IntPair>{public bool Equals(IntPair a,IntPair b)=>a.x==b.x&&a.y==b.y;public int GetHashCode(IntPair p)=>p.x*397^p.y;}}
}
